    if model=='kvadro':
        intro='Квадро стоит рассмотреть, если вам важны центральный вынесенный вход и ширина 2,1 м. Вход уже включён в базовую цену. Можно выбрать одну из пяти длин от 4 до 6 м и дополнить баню под свой отдых.'
        detail='Начните с размера: Квадро 4 м — '+money(price(book,model,'400'))+', 5 м — '+money(five)+', 6 м — '+money(price(book,model,'600'))+'. Затем выберите, что важно именно вам: больше света, удобное хранение, стеклянная дверь или дополнительное оснащение парной.'
        compare='Для сравнения одной длины: Парус 5 м стоит '+money(price(book,'parus','500'))+' при ширине 2,4 м; Викинг 5 м — '+money(price(book,'viking','500'))+' при той же ширине 2,4 м и арочном центральном входе. Квадро 5 м имеет ширину 2,1 м и стоит '+money(five)+'. Это сравнение внешних габаритов и базовых цен; точный состав каждого исполнения проверяйте отдельно.'
        extras=section('База или Комфорт для Квадро 5 м?',p('В базе за '+money(five)+' уже есть печь и основное оснащение. Комфорт стоит '+money(comfort(book))+': доплата '+money(comfort(book)-five)+' — за свет, хранение, утепление пола и другие выбранные удобства.')+links([('../../journal/kvadro-5-komfort/','Что добавляет Комфорт'),('../../journal/iz-chego-skladyvaetsya-tsena/','Как складывается стоимость заказа')]))
